import {money,cents,categoryList,today,validateBackup} from './domain.mjs';
import {SHORTCUTS} from './daily-schema.mjs';
import {dailyPrefs,updateDaily,saveTemplate,templateDraft,lastDraft,saveMerchantRule,merchantMatch,applyMerchantRules,ledgerFingerprint,backupHealth} from './daily-core.mjs';
import {decryptBackup} from './backup.mjs';

export function createDailyUI(c){
  const {E,I,toast,openSheet,download}=c,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
  const state=()=>c.getState(),prefs=()=>dailyPrefs(state()),book=()=>c.getBook(),bookId=()=>book()==='all'?'personal':book();
  const scope=()=>c.getStorageKey(),metaKey=key=>'yoyu-backup-health-v1:'+key;
  const readMeta=()=>{try{const m=JSON.parse(localStorage.getItem(metaKey(scope()))||'{}');return m&&typeof m==='object'&&!Array.isArray(m)?m:{}}catch{return {}}};
  const saveMeta=(key,value)=>localStorage.setItem(metaKey(key),JSON.stringify(value));
  const error='<div class="inline-error" id="daily-error" role="alert"></div>';
  const fail=e=>{const el=$('#daily-error');if(el)el.textContent=e.message;else toast(e.message);};
  const finish=(next,message)=>{if(c.commit(next)){c.render();$('#sheet').close();toast(message);return true;}return false;};
  const input=(label,id,value='',extra='')=>`<label class="field">${label}<input id="${id}" value="${E(value)}" ${extra}></label>`;
  const select=(label,id,options,value)=>`<label class="field">${label}<select id="${id}">${options.map(([id,name])=>`<option value="${E(id)}" ${id===value?'selected':''}>${E(name)}</option>`).join('')}</select></label>`;
  const types=[['expense','支出'],['income','收入']],books=()=>state().features.books.map(b=>[b.id,b.name]);
  const categories=()=>categoryList(state()).map(v=>[v,v]);
  const accountName=id=>state().accounts.find(a=>a.id===id)?.name||'未指定';
  const visibleTemplates=()=>prefs().templates.filter(t=>book()==='all'||t.bookId===book());
  function templatePanel(){const rows=visibleTemplates();return `<div class="card daily-templates"><div class="card-heading"><h2>常用範本</h2><button class="text-btn" data-daily="templates">管理</button></div><div class="template-chips">${rows.slice(0,8).map(t=>`<button class="template-chip" data-template-use="${E(t.id)}"><strong>${E(t.name)}</strong><small>${t.amount?`<span class="sensitive">${money(t.amount)}</span>`:'金額再填'} · ${E(accountName(t.account))}</small></button>`).join('')||'<p class="help">把常記的早餐、咖啡、停車存成範本，下次一點帶入。</p>'}</div><div class="row daily-row"><button class="text-btn" data-daily="new-template">＋ 新增範本</button><button class="text-btn" data-daily="copy-last">複製最近一筆</button></div></div>`;}
  function reminder(){if(c.isDemo())return '';const h=backupHealth(readMeta(),{hasData:state().transactions.length>0});return h.remind?`<div class="backup-reminder"><span>${E(h.label)}。本機歷史版本仍在同一裝置。</span><button class="text-btn" data-daily="health">檢查備份</button><button class="text-btn" data-daily="snooze">明天再提醒</button></div>`:'';}
  function mobileHome({summary,recentHTML,availableHTML}){return `<div class="mobile-home"><div class="page-title"><div><div class="eyebrow">A LITTLE ROOM, EVERY DAY</div><h1>今天，留點餘裕。</h1><p class="subtitle">先記一筆，其他慢慢來。</p></div></div><div class="card mobile-spend"><span>本月支出 · ${E(c.getMonth())}</span><strong class="sensitive">${money(summary.expense)}</strong><small>收入 <span class="sensitive">${money(summary.income)}</span> · 結餘 <span class="sensitive">${money(summary.net)}</span></small><button class="primary full" data-new="">${I('plus')}記一筆</button></div><div class="card mobile-shortcuts"><div class="card-heading"><h2>我的捷徑</h2><button class="text-btn" data-daily="shortcuts">自訂</button></div><div class="shortcut-grid">${prefs().shortcuts.map(key=>`<button data-shortcut="${key}"><span>${I({scan:'camera',bills:'book',available:'leaf',ai:'spark',ledger:'book',plans:'card',settlements:'wallet',accounts:'wallet',reports:'chart'}[key])}</span>${SHORTCUTS[key]}</button>`).join('')}</div></div>${templatePanel()}${availableHTML}${reminder()}<div class="card"><div class="card-heading"><h2>最近記下的日常</h2><button class="text-btn" data-page="ledger">查看全部</button></div>${recentHTML}</div><button class="secondary full" data-daily="toggle-layout">切換完整首頁</button></div>`;}
  function settingsPanel(){const h=backupHealth(readMeta(),{hasData:state().transactions.length>0});return `<div class="card daily-settings"><div class="card-heading"><h2>日常捷徑與記帳習慣</h2><span class="pill">不需要 AI Key</span></div><p class="help">手機目前使用${prefs().compact?'精簡':'完整'}首頁；電腦保留完整總覽。範本與分類規則會隨帳本備份保存。</p><div class="row daily-row"><button class="secondary" data-daily="shortcuts">首頁與捷徑</button><button class="secondary" data-daily="templates">常用範本（${prefs().templates.length}）</button><button class="secondary" data-daily="rules">商家分類（${prefs().rules.length}）</button></div></div><div class="card daily-settings"><div class="card-heading"><h2>備份健康檢查</h2><span class="pill">${c.isDemo()?'示範模式':E(h.label)}</span></div><p class="help">本機歷史版本不等於外部備份。這裡追蹤完整 JSON 匯出與你選取的備份檔案，可驗證格式及是否與目前帳本一致，不會還原或覆寫帳目。</p><button class="secondary" data-daily="health">查看與檢查備份</button></div>`;}
  function shortcutSheet(){const p=prefs();openSheet('手機首頁與捷徑',`<form id="daily-shortcuts"><label class="check"><input type="checkbox" id="daily-compact" ${p.compact?'checked':''}>手機使用精簡首頁</label><p class="help">依下方順序顯示最多四個捷徑，其他功能仍可由設定與完整首頁開啟。</p>${Array.from({length:4},(_,i)=>select(`捷徑 ${i+1}`,'shortcut-'+i,[['','不顯示'],...Object.entries(SHORTCUTS)],p.shortcuts[i]||'')).join('')}${error}<button class="primary full">儲存首頁設定</button></form>`);$('#daily-shortcuts').onsubmit=e=>{e.preventDefault();try{finish(updateDaily(state(),{compact:$('#daily-compact').checked,shortcuts:[0,1,2,3].map(i=>$('#shortcut-'+i).value).filter(Boolean)}),'首頁捷徑已更新')}catch(e){fail(e)}};}
  function templatesSheet(){openSheet('我的常用範本',`<p class="help">範本只帶入表單，不會自動入帳。每個帳本最多共40個範本，未填金額的範本可在記帳時再填。</p><button class="primary" id="new-daily-template">＋ 新增範本</button>${prefs().templates.map(t=>`<div class="due-row"><div><strong>${E(t.name)}</strong><small>${E(state().features.books.find(b=>b.id===t.bookId)?.name)} · ${E(t.note)} · ${E(accountName(t.account))} · <span class="sensitive">${t.amount?money(t.amount):'金額再填'}</span></small></div><button class="text-btn" data-template-edit="${E(t.id)}">編輯</button><button class="text-btn" data-template-delete="${E(t.id)}">刪除</button></div>`).join('')||'<p class="help">還沒有範本，先建立一個最常用的。</p>'}`);$('#new-daily-template').onclick=()=>templateSheet();$$('[data-template-edit]').forEach(b=>b.onclick=()=>templateSheet(b.dataset.templateEdit));$$('[data-template-delete]').forEach(b=>b.onclick=()=>{if(confirm('刪除這個範本？既有交易不會改變。')){if(finish(updateDaily(state(),{templates:prefs().templates.filter(t=>t.id!==b.dataset.templateDelete)}),'範本已刪除'))templatesSheet();}});}
  function templateSheet(id=null,preset={}){
    const t=prefs().templates.find(t=>t.id===id)||{name:preset.note||'',note:'',type:'expense',amount:0,category:'餐飲',account:state().accounts.find(a=>a.kind!=='receivable')?.id,bookId:bookId(),...preset};
    openSheet(id?'編輯記帳範本':'新增記帳範本',`<form id="daily-template-form">${input('範本名稱','template-name',t.name,'required maxlength="40"')}${input('帶入的項目名稱','template-note',t.note,'required maxlength="200"')}<div class="row">${select('類型','template-type',types,t.type)}${input('金額（NT$，留空則每次填寫）','template-amount',t.amount?t.amount/100:'','type="number" min="0" max="10000000000" step="0.01" inputmode="decimal"')}</div>${select('使用帳戶','template-account',state().accounts.filter(a=>a.kind!=='receivable').map(a=>[a.id,a.name]),t.account)}<div class="row">${select('分類','template-category',categories(),t.category)}${select('所屬帳本','template-book',books(),t.bookId)}</div>${error}<button class="primary full">只儲存範本</button><p class="help">不會新增、修改或刪除任何交易。</p></form>`);
    $('#daily-template-form').onsubmit=e=>{e.preventDefault();try{finish(saveTemplate(state(),{name:$('#template-name').value,note:$('#template-note').value,type:$('#template-type').value,amount:cents($('#template-amount').value||0),category:$('#template-category').value,account:$('#template-account').value,bookId:$('#template-book').value},id),'範本已儲存，下次可從首頁帶入')}catch(e){fail(e)}};
  }
  function rulesSheet(){openSheet('商家自動分類',`<p class="help">規則只適用指定帳本與收支類型。項目名稱包含商家關鍵字時，自動帶入分類；完全相同的名稱優先，再選最長關鍵字。既有紀錄不會被改動。</p><button class="primary" id="new-merchant-rule">＋ 新增規則</button>${prefs().rules.map(r=>`<div class="due-row"><div><strong>${E(r.pattern)} → ${E(r.category)}</strong><small>${E(state().features.books.find(b=>b.id===r.bookId)?.name)} · ${{expense:'支出',income:'收入',refund:'退款'}[r.type]} · ${r.enabled?'使用中':'已停用'}</small></div><button class="text-btn" data-rule-edit="${E(r.id)}">編輯</button><button class="text-btn" data-rule-toggle="${E(r.id)}">${r.enabled?'停用':'啟用'}</button><button class="text-btn" data-rule-delete="${E(r.id)}">刪除</button></div>`).join('')||'<p class="help">你也可以在記帳時勾選「記住這個商家的分類」。</p>'}`);$('#new-merchant-rule').onclick=()=>ruleSheet();$$('[data-rule-edit]').forEach(b=>b.onclick=()=>ruleSheet(b.dataset.ruleEdit));$$('[data-rule-toggle]').forEach(b=>b.onclick=()=>{try{const r=prefs().rules.find(r=>r.id===b.dataset.ruleToggle);if(finish(saveMerchantRule(state(),{...r,enabled:!r.enabled},r.id),'分類規則已更新'))rulesSheet()}catch(e){toast(e.message)}});$$('[data-rule-delete]').forEach(b=>b.onclick=()=>{if(confirm('刪除這個分類規則？既有交易不會改變。')){if(finish(updateDaily(state(),{rules:prefs().rules.filter(r=>r.id!==b.dataset.ruleDelete)}),'分類規則已刪除'))rulesSheet();}});}
  function ruleSheet(id=null){const r=prefs().rules.find(r=>r.id===id)||{pattern:'',category:'餐飲',bookId:bookId(),type:'expense',enabled:true};openSheet('設定商家分類',`<form id="merchant-rule-form">${input('商家／關鍵字（至少2個字元）','rule-pattern',r.pattern,'required minlength="2" maxlength="60" placeholder="例如：全家、星巴克"')}${select('分類','rule-category',categories(),r.category)}<div class="row">${select('所屬帳本','rule-book',books(),r.bookId)}${select('適用類型','rule-type',[...types,['refund','退款']],r.type)}</div>${error}<button class="primary full">儲存分類規則</button></form>`);$('#merchant-rule-form').onsubmit=e=>{e.preventDefault();try{finish(saveMerchantRule(state(),{pattern:$('#rule-pattern').value,category:$('#rule-category').value,bookId:$('#rule-book').value,type:$('#rule-type').value,enabled:r.enabled},id),'商家分類已記住')}catch(e){fail(e)}};}
  const time=at=>Number.isFinite(at)?new Date(at).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}):'尚無紀錄';
  function assertReal(){if(c.isDemo())throw Error('請先回到我的帳本，再檢查或記錄真實備份');if(c.isCorrupt())throw Error('原始帳本無法讀取，請先下載原始資料或還原有效備份');}
  async function inspectCurrent(){assertReal();const original=state(),key=scope(),current=validateBackup(original),hash=await ledgerFingerprint(current);if(state()!==original||scope()!==key)throw Error('檢查期間帳本已變更，請重新檢查');return {current,hash};}
  async function healthSheet(){const m=readMeta(),h=backupHealth(m,{hasData:state().transactions.length>0});openSheet('備份健康檢查',`<p class="notice">${E(h.label)}。${c.isDemo()?'示範模式不記錄真實備份狀態。':'提醒只在網頁／APP 開啟時出現。'}</p><p class="help">上次產生完整 JSON：${E(time(m.exported?.at))}<br>上次選檔驗證：${E(time(m.verified?.at))}<br>此工具無法確認瀏覽器下載是否已存入你指定的位置，請保留檔案並用「選擇備份檔驗證」確認。</p><div class="row daily-row"><button class="primary" id="health-download">產生完整備份</button><button class="secondary" id="health-current">檢查目前帳本</button><button class="secondary" id="health-pick">選擇備份檔驗證</button></div><input type="file" id="health-file" accept="application/json,.json" hidden><p id="health-result" role="status" class="help">驗證不會還原、合併或覆寫任何資料；支援完整 JSON 與加密備份。</p><form id="health-reminder-form">${select('多久提醒一次','health-days',[[1,'每天'],[3,'每3天'],[7,'每週'],[14,'每兩週'],[30,'每月']],h.days)}<button class="secondary">儲存提醒頻率</button></form>${error}`);
    $('#health-reminder-form').onsubmit=e=>{e.preventDefault();try{assertReal();saveMeta(scope(),{...readMeta(),remindDays:Number($('#health-days').value),snoozeUntil:0});toast('備份提醒頻率已更新')}catch(e){fail(e)}};
    $('#health-download').onclick=()=>{try{assertReal();const checked=validateBackup(state());download(JSON.stringify(checked,null,2),'日常有餘_完整備份_'+today()+'.json','application/json');$('#health-result').textContent='已產生通過格式檢查的完整備份。請完成瀏覽器下載，再選取該檔案驗證。';}catch(e){fail(e)}};
    $('#health-current').onclick=async()=>{const key=scope();try{const {current,hash}=await inspectCurrent();if(scope()!==key)return;const m=readMeta();$('#health-result').textContent=`目前帳本格式正常：${current.transactions.length} 筆交易、${current.accounts.length} 個帳戶。`+(m.latest?.fingerprint===hash?' 與最近記錄的完整備份一致。':' 目前帳本尚未與最近備份確認一致，請產生並驗證新備份。');}catch(e){if(scope()===key)fail(e)}};
    $('#health-pick').onclick=()=>$('#health-file').click();$('#health-file').onchange=async e=>{const file=e.target.files[0],key=scope();e.target.value='';if(!file)return;try{assertReal();if(file.size>25*1024*1024)throw Error('備份超過25MB');const raw=JSON.parse(await file.text());if(scope()!==key)return;if(raw?.format==='yoyu-encrypted-v1'){openSheet('驗證加密備份',`<form id="health-decrypt">${input('備份密碼（僅用於本次驗證）','health-password','','type="password" required minlength="8" autocomplete="off"')}${error}<button class="primary full">解密並驗證，不還原</button></form>`);$('#health-decrypt').onsubmit=async ev=>{ev.preventDefault();try{const password=$('#health-password').value;$('#health-password').value='';await verifyFile(await decryptBackup(raw,password),key)}catch(e){if(scope()===key)fail(e)}};}else await verifyFile(raw,key);}catch(e){if(scope()===key)fail(Error('無法驗證備份：'+e.message))}};
  }
  async function verifyFile(raw,key){const checked=validateBackup(raw),hash=await ledgerFingerprint(checked);if(scope()!==key)return;assertReal();const original=state(),currentHash=await ledgerFingerprint(original);if(scope()!==key)return;const matches=state()===original&&hash===currentHash,at=Date.now(),meta=readMeta();saveMeta(key,{...meta,verified:{at,fingerprint:hash,matches},...(matches?{latest:{at,fingerprint:hash},snoozeUntil:0}:{})});openSheet('備份驗證結果',`<div class="notice ${matches?'':'warn'}">備份格式有效，包含 ${checked.transactions.length} 筆交易與 ${checked.accounts.length} 個帳戶。<br>${matches?'檔案與目前帳本內容一致。':'檔案與目前帳本不同，可能是舊版本或其他帳本；不會標記目前帳本已完成備份。'}</div><p class="help">已檢查帳目與關聯資料格式${raw?.format==='yoyu-encrypted-v1'?'及解密':''}，沒有還原或改動帳目。這不保證檔案未來不會遺失，請保留副本。</p>`);c.render();}
  async function onDownload(content){if(c.isDemo())return;let checked;try{checked=validateBackup(JSON.parse(content))}catch{return;}const key=scope(),at=Date.now(),hash=await ledgerFingerprint(checked);if(scope()!==key)return;const m=readMeta();saveMeta(key,{...m,exported:{at,fingerprint:hash},latest:{at,fingerprint:hash},snoozeUntil:0});}
  function entryExtras(t){if(t.type==='transfer')return '';return `<p class="help" id="merchant-hint" role="status"></p><label class="check"><input type="checkbox" id="merchant-remember"><span>記住這個商家的分類（只套用此帳本與收支類型）</span></label>${input('商家關鍵字（勾選記住時使用）','merchant-pattern','','maxlength="60" placeholder="例如：全家；留空則使用完整項目名稱"')}`;}
  function bindEntry(t){let touched=!!t._editing||!!t._fromTemplate;const initial=t.category;const suggest=()=>{if(touched||t.type==='transfer')return;const match=merchantMatch(state(),{note:$('#entry-note').value,type:t.type,bookId:$('#entry-book').value});t.category=match?.category||initial;$$('[data-category]').forEach(b=>b.classList.toggle('active',b.dataset.category===t.category));$('#merchant-hint').textContent=match?'已帶入「'+match.pattern+'」的分類：'+match.category+'，可手動更改。':'';};$('#entry-note')?.addEventListener('input',suggest);$('#entry-book')?.addEventListener('change',suggest);$$('[data-category]').forEach(b=>b.addEventListener('click',()=>{touched=true;$('#merchant-hint')&&( $('#merchant-hint').textContent='使用你手動選擇的分類。');}));suggest();}
  function withLearnedRule(next,t){if(!$('#merchant-remember')?.checked||t.type==='transfer')return next;return saveMerchantRule(next,{pattern:$('#merchant-pattern').value.trim()||t.note,category:t.category,bookId:t.bookId,type:t.type,enabled:true});}
  function bind(){
    $$('[data-template-use]').forEach(b=>b.onclick=()=>{try{c.openEntry(null,{...templateDraft(state(),b.dataset.templateUse),_fromTemplate:true})}catch(e){toast(e.message)}});
    $$('[data-shortcut]').forEach(b=>b.onclick=()=>{if(b.dataset.shortcut==='scan')c.scanInvoice();else if(b.dataset.shortcut==='ai')c.openAI();else c.navigate(b.dataset.shortcut)});
    $$('[data-daily]').forEach(b=>b.onclick=()=>{try{const action=b.dataset.daily;if(action==='shortcuts')shortcutSheet();else if(action==='templates')templatesSheet();else if(action==='new-template')templateSheet();else if(action==='rules')rulesSheet();else if(action==='health')healthSheet();else if(action==='copy-last')c.openEntry(null,{...lastDraft(state(),book()),_fromTemplate:true});else if(action==='toggle-layout')finish(updateDaily(state(),{compact:!prefs().compact}),'手機首頁已切換');else if(action==='snooze'){assertReal();saveMeta(scope(),{...readMeta(),snoozeUntil:Date.now()+86400000});c.render();}}catch(e){toast(e.message)}});
  }
  return {prefs,templatePanel,mobileHome,settingsPanel,reminder,bind,entryExtras,bindEntry,withLearnedRule,onDownload,classify:rows=>applyMerchantRules(state(),rows),saveEntryTemplate:t=>templateSheet(null,{...t,name:t.note}),inspectCurrent};
}
